/usr/bin/bash -lc "python - <<'PY'
def make_implicit():
    try:
        raise ValueError('meaningful')
    except ValueError:
        try:
            raise RuntimeError('application')
        except RuntimeError as exc:
            return exc

def show(label, exc):
    print(label, type(exc.__context__).__name__ if exc.__context__ else None, type(exc.__cause__).__name__ if exc.__cause__ else None)

exc = make_implicit()
show('stored', exc)
try:
    raise EOFError('internal')
except EOFError:
    try:
        raise exc
    except RuntimeError as raised:
        show('inside-except', raised)

exc = make_implicit()
try:
    try:
        raise EOFError('internal')
    except EOFError:
        deferred = exc
    raise deferred
except RuntimeError as raised:
    show('deferred', raised)
PY
